module rtcl_p3s7_blinking_led
        #(
            parameter   int COUNT_LIMIT = 50_000_000
        )
        (
            input   var logic           clk50   ,
            input   var logic           clk72   ,
            output  var logic   [1:0]   led     ,
            output  var logic   [7:0]   pmod    
        );
logic   [31:0]   counter_50;
    logic   [31:0]   counter_72;

    always_ff @(posedge clk50) begin
        if (counter_50 == COUNT_LIMIT) begin
            counter_50 <= 0;
        end else begin
            counter_50 <= counter_50 + 1;
        end
    end

    always_ff @(posedge clk72) begin
        if (counter_72 == COUNT_LIMIT) begin
            counter_72 <= 0;
        end else begin
            counter_72 <= counter_72 + 1;
        end
    end

    assign led[0] = counter_50[31];
    assign led[1] = counter_72[31];

    assign pmod = counter_72[31:24];

endmodule

