module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
reg [3:0] counter;
    reg [3:0] index;
    reg [9:0] keypress_array [0:15];
    initial begin
        keypress = 0;
        counter = 0;
        index = 0;
    end
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            keypress = 0;
            counter = 0;
            index = 0;
        end
        else begin
            if (counter == 20) begin
                keypress = keypress_array[index];
                counter = 0;
                index = index + 1;
            end
            else begin
                counter = counter + 1;
            end
        end
    end
    always @(keypress_array) begin
        keypress_array[0] = 10'b0000000000;
        keypress_array[1] = 10'b0000000001;
        keypress_array[2] = 10'b0000000010;
        keypress_array[3] = 10'b0000000011;
        keypress_array[4] = 10'b0000000100;
        keypress_array[5] = 10'b0000000101;
        keypress_array[6] = 10'b0000000110;
        keypress_array[7] = 10'b0000000111;
        keypress_array[8] = 10'b0000001000;
        keypress_array[9] = 10'b0000001001;
        keypress_array[10] = 10'b0000001010;
        keypress_array[11] = 10'b0000001011;
        keypress_array[12] = 10'b0000001100;
        keypress_array[13] = 10'b0000001101;
        keypress_array[14] = 10'b0000001110;
        keypress_array[15] = 10'b0000001111;
    end
endmodule

