module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);
logic [WIDTH-1:0] dat0;
logic [WIDTH-1:0] dat1;
logic [2:0] state;
logic [2:0] next_state;

assign t0_ready = i0_ready;
assign i0_data = (state == S0) ? dat0 : dat1;
assign i0_valid = (state == S0) ? t0_valid : t0_valid;

always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		state <= S0;
	end else begin
		state <= next_state;
	end
end

always_comb begin
	case (state)
		S0: begin
			if (t0_valid && i0_ready) begin
				next_state = S1;
			end else begin
				next_state = S0;
			end
		end
		S1: begin
			if (t0_valid && !i0_ready) begin
				next_state = S2;
			end else begin
				next_state = S1;
			end
		end
		S2: begin
			if (!t0_valid && i0_ready) begin
				next_state = S3;
			end else begin
				next_state = S2;
			end
		end
		S3: begin
			if (!t0_valid && !i0_ready) begin
				next_state = S4;
			end else begin
				next_state = S3;
			end
		end
		S4: begin
			if (t0_valid && !i0_ready) begin
				next_state = S0;
			end else begin
				next_state = S4;
			end
		end
		default: next_state = S0;
	endcase
end

always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		dat0 <= '0;
		dat1 <= '0;
	end else begin
		case (state)
			S0: dat0 <= t0_data;
			S1: dat0 <= t0_data;
			S2: dat1 <= t0_data;
			S3: dat1 <= t0_data;
			S4: dat0 <= t0_data;
			default: dat0 <= '0;
		endcase
	end
end

endmodule

module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg     [WIDTH-1:0]     mem [0:DEPTH-1];
reg     [3:0]            word_count;
reg     [3:0]            write_ptr;
reg     [3:0]            read_ptr;
reg     [3:0]            prog_full_count;

assign data_o = mem[read_ptr];
assign full = (word_count == DEPTH);
assign empty = (word_count == 0);
assign prog_full = (prog_full_count == PROG_FULL);

always @(posedge clk or posedge reset_p) begin
    if (reset_p) begin
        write_ptr <= 0;
        read_ptr <= 0;
        prog_full_count <= 0;
        overflow <= 0;
        underflow <= 0;
    end else begin
        if (data_we) begin
            if (full) begin
                overflow <= 1;
                underflow <= 0;
            end else begin
                mem[write_ptr] <= data_i;
                write_ptr <= write_ptr + 1;
                if (write_ptr == read_ptr) begin
                    prog_full_count <= prog_full_count + 1;
                end
            end
        end
        if (data_rd) begin
            if (empty) begin
                overflow <= 0;
                underflow <= 1;
            end else begin
                read_ptr <= read_ptr + 1;
                if (read_ptr == write_ptr) begin
                    prog_full_count <= prog_full_count - 1;
                end
            end
        end
    end
end

endmodule

