module counter
#(
  parameter integer WIDTH=5
 )
 (
  input  wire clk  ,
  input  wire rst  ,
  input  wire load ,
  input  wire enab ,
  input  wire [WIDTH-1:0] cnt_in ,
  output reg  [WIDTH-1:0] cnt_out 
 );
reg [WIDTH-1:0] cnt_tmp;

  always @(*) begin
    if (rst) begin
      cnt_tmp = 0;
    end else if (load) begin
      cnt_tmp = cnt_in;
    end else if (enab) begin
      cnt_tmp = cnt_out + 1;
    end else begin
      cnt_tmp = cnt_out;
    end
  end

  always @(posedge clk) begin
    cnt_out <= cnt_tmp;
  end

endmodule

