reg tx_busy_reg;

reg [7:0] rx_shift_reg;
reg [3:0] rx_cnt;
reg rx_busy_reg;

reg rx_frame_error_reg;

assign uart_tx = tx_busy_reg ? tx_shift_reg[0] : 1'b0;
assign rx_vld = rx_busy_reg ? rx_shift_reg[0] : 1'b0;

always @(posedge clk_50) begin
    if (rst) begin
        tx_busy_reg <= 1'b0;
        tx_cnt <= 4'd0;
        tx_shift_reg <= 8'd0;
        tx_frame_error_reg <= 1'b0;
    end else begin
        if (tx_busy_reg) begin
            if (tx_cnt == 4'd7) begin
                tx_busy_reg <= 1'b0;
            end else begin
                tx_shift_reg <= {tx_shift_reg[6:0], tx_data[tx_cnt]};
                tx_cnt <= tx_cnt + 4'd1;
            end
        end else begin
            if (tx_vld) begin
                tx_busy_reg <= 1'b1;
                tx_cnt <= 4'd0;
                tx_shift_reg <= tx_data;
            end
        end
    end
end

always @(posedge clk_50) begin
    if (rst) begin
        rx_busy_reg <= 1'b0;
        rx_cnt <= 4'd0;
        rx_shift_reg <= 8'd0;
        rx_frame_error_reg <= 1'b0;
    end else begin
        if (rx_busy_reg) begin
            if (rx_cnt == 4'd7) begin
                rx_busy_reg <= 1'b0;
            end else begin
                rx_shift_reg <= {rx_shift_reg[6:0], uart_rx};
                rx_cnt <= rx_cnt + 4'd1;
            end
        end else begin
            if (rx_vld) begin
                rx_busy_reg <= 1'b1;
                rx_cnt <= 4'd0;
                rx_shift_reg <= {1'b0, uart_rx};
            end
        end
    end
end

always @(posedge clk_50) begin
    if (rst) begin
        rx_frame_error_reg <= 1'b0;
    end else begin
        if (rx_busy_reg) begin
            if (rx_cnt == 4'd7) begin
                if (rx_shift_reg[0] != rx_shift_reg[1] || rx_shift_reg[0] != rx_shift_reg[2] || rx_shift_reg[0] != rx_shift_reg[3] || rx_shift_reg[0] != rx_shift_reg[4] || rx_shift_reg[0] != rx_shift_reg[5] || rx_shift_reg[0] != rx_shift_reg[6] || rx_shift_reg[0] != rx_shift_reg[7]) begin
                    rx_frame_error_reg <= 1'b1;
                end else begin
                    rx_frame_error_reg <= 1'b0;
                end
            end
        end else begin
            if (rx_shift_reg[0] != rx_shift_reg[1] || rx_shift_reg[0] != rx_shift_reg[2] || rx_shift_reg[0] != rx_shift_reg[3] || rx_shift_reg[0] != rx_shift_reg[4] || rx_shift_reg[0] != rx_shift_reg[5] || rx_shift_reg[0] != rx_shift_reg[6] || rx_shift_reg[0] != rx_shift_reg[7]) begin
                rx_frame_error_reg <= 1'b1;
            end else begin
                rx_frame_error_reg <= 1'b0;
            end
        end
    end
end

