   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 2'b00;
   localparam DATA0 = 2'b01;
   localparam DATA1 = 2'b10;
   reg [1:0] state, next_state;
   assign dst_rdy_o = dst0_rdy_i | dst1_rdy_i;
   assign src0_rdy_o = src_rdy_i & dst0_rdy_i;
   assign src1_rdy_o = src_rdy_i & dst1_rdy_i;
   assign data0_o = (state == DATA0) ? data_i : 0;
   assign data1_o = (state == DATA1) ? data_i : 0;
   always @(posedge clk or posedge reset)
     if (reset)
       state <= IDLE;
     else
       state <= next_state;
   always @*
     case (state)
       IDLE: if (src_rdy_i & match_data & match_mask)
		next_state = DATA0;
		else if (dst0_rdy_i)
		  next_state = DATA1;
		else
		  next_state = IDLE;
       DATA0: if (src_rdy_i & match_data & match_mask)
		next_state = DATA0;
		else if (dst0_rdy_i)
		  next_state = DATA1;
		else
		  next_state = IDLE;
       DATA1: if (src_rdy_i & match_data & match_mask)
		next_state = DATA1;
		else if (dst1_rdy_i)
		  next_state = DATA0;
		else
		  next_state = IDLE;
       default: next_state = IDLE;
     endcase
