module arriaiigz_ff (
    d, 
    clk, 
    clrn, 
    aload, 
    sclr, 
    sload, 
    asdata, 
    ena, 
    devclrn, 
    devpor, 
    q
    );

input d;
input clk;
input clrn;
input aload; 
input sclr; 
input sload; 
input asdata; 
input ena; 
input devclrn; 
input devpor; 

output q;
parameter power_up = "low";
parameter violation = "on";
parameter lpm_type = "arriaiigz_ff";

tri1 devclrn;
tri1 devpor;

reg q_tmp;
reg violation_tmp;

reg clk_last_value;
reg sclr_last_value;
reg sload_last_value;
reg asdata_last_value;
reg ena_last_value;

reg reset;

wire resetn = ~reset;

specify
    $setuphold (posedge clk &&& resetn, d, 0, 0, violation_tmp, devpor) ;
    $setuphold (posedge clk &&& resetn, ena, 0, 0, violation_tmp, devpor) ;
    $setuphold (posedge clk &&& resetn, sclr, 0, 0, violation_tmp, devpor) ;
    $setuphold (posedge clk &&& resetn, sload, 0, 0, violation_tmp, devpor) ;
    $setuphold (posedge clk &&& resetn, asdata, 0, 0, violation_tmp, devpor) ;
    (posedge clk => (q +: q_tmp)) = 0 ;
endspecify

initial
begin
    clk_last_value = 'b0;
    sclr_last_value = 'b0;
    sload_last_value = 'b0;
    asdata_last_value = 'b0;
    ena_last_value = 'b1;
    q_tmp = 'b0;
    violation_tmp = 'b0;
    reset = 'b0;
end

assign q = q_tmp;

always @ (clk or devpor or devclrn)
begin
    if (devpor === 'b0)
    begin
        q_tmp <= 'b0;
        violation_tmp <= 'b0;
    end
    else if (devclrn === 'b0)
    begin
        q_tmp <= 'b0;
        violation_tmp <= 'b0;
    end
    else
    begin
        if (ena_last_value === 'b1)
        begin
            if (sclr_last_value === 'b1)
            begin
                q_tmp <= 'b0;
                violation_tmp <= 'b0;
            end
            else if (sload_last_value === 'b1)
            begin
                q_tmp <= 'b1;
                violation_tmp <= 'b0;
            end
            else if (asdata_last_value === 'b1)
            begin
                q_tmp <= 'b1;
                violation_tmp <= 'b0;
            end
            else if (clk_last_value === 'b1)
            begin
                q_tmp <= 'b1;
                violation_tmp <= 'b0;
            end
            else if (violation_tmp === 'b1)
            begin
                q_tmp <= 'bX;
                violation_tmp <= 'b1;
            end
        end
    end

    clk_last_value <= clk;
    sclr_last_value <= sclr;
    sload_last_value <= sload;
    asdata_last_value <= asdata;
    ena_last_value <= ena;
end

endmodule

