  reg [7:0] data;
  assign io_ready = state == 0;
  assign tx = state[0] ? data[0] : 1;
  always @(posedge clock) begin
    if (reset) begin
      state <= 0;
      data <= 0;
    end else if (tick) begin
      if (io_valid && io_ready) begin
        state <= 0;
        data <= io_bits;
      end else begin
        if (state == 0) begin
          state <= 1;
          data <= {data[6:0], 1'b1};
        end else begin
          state <= state + 1;
          data <= {data[6:0], 1'b0};
        end
      end
    end
  end
endmodule

