module rbw_check(
    input wire          clk,        
    input wire          a_rst,      
    input wire          i_rbw,      
    input wire[L:0]     i_rbw_adr,  
    input wire          rs,         
    input wire          r_ts,       
    input wire[L:0]     rs_adr,     
    input wire          ws,         
    input wire          w_ts,       
    input wire[L:0]     ws_adr,     
    output wire         o_rbw       
);
parameter L = 10;  

    reg rbw;
    reg [L-1:0] rbw_adr;
    reg [L-1:0] rbw_ts;
    reg rbw_valid;
    reg rbw_valid_next;

    always @(posedge clk or negedge a_rst) begin
        if (!a_rst) begin
            rbw <= 1'b0;
            rbw_adr <= {L{1'b0}};
            rbw_ts <= {L{1'b0}};
            rbw_valid <= 1'b0;
        end else begin
            rbw <= i_rbw;
            rbw_adr <= i_rbw_adr;
            rbw_ts <= r_ts ? rbw_ts : {L{1'b0}};
            rbw_valid <= rbw_valid_next;
        end
    end

    always @(rbw, rbw_adr, rbw_ts, rs, r_ts, rs_adr, r_ts, ws, w_ts, ws_adr, w_ts) begin
        rbw_valid_next = 1'b0;
        if (rbw) begin
            rbw_valid_next = 1'b1;
            if (rs && (rbw_adr == rs_adr) && (rbw_ts == r_ts)) begin
                rbw_valid_next = 1'b0;
            end
            if (ws && (rbw_adr == ws_adr) && (rbw_ts == w_ts)) begin
                rbw_valid_next = 1'b0;
            end
        end
    end

    assign o_rbw = rbw_valid;

endmodule

