module sqrt_pipelined
  #(
    parameter
    INPUT_BITS   = 16, 
    OUTPUT_BITS  = INPUT_BITS / 2 + INPUT_BITS % 2 
    )
  (
   input                        clk,        
   input                        reset_n,    
   input                        start,      
   input [INPUT_BITS-1:0]       radicand,   
   output reg                   data_valid, 
   output reg [OUTPUT_BITS-1:0] root        
   );
localparam
    PIPE_STAGES = OUTPUT_BITS / 2 + OUTPUT_BITS % 2;

    reg [PIPE_STAGES-1:0] start_gen;
    reg [PIPE_STAGES-1:0] radicand_gen;
    reg [PIPE_STAGES-1:0] root_gen;
    reg [PIPE_STAGES-1:0] mask_gen;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            start_gen <= 0;
            radicand_gen <= 0;
            root_gen <= 0;
            mask_gen <= 0;
        end
        else begin
            if (start) begin
                start_gen <= 0;
                radicand_gen <= radicand;
                root_gen <= 0;
                mask_gen <= 1;
            end
            else begin
                start_gen <= start_gen + 1;
                radicand_gen <= radicand_gen >> 1;
                root_gen <= root_gen >> 1;
                mask_gen <= mask_gen << 1;
            end
        end
    end

    generate
        genvar i;
        for (i = 0; i < PIPE_STAGES; i = i + 1) begin : gen_pipe
            always @(posedge clk or negedge reset_n) begin
                if (!reset_n) begin
                    start_gen[i] <= 0;
                    radicand_gen[i] <= 0;
                    root_gen[i] <= 0;
                    mask_gen[i] <= 0;
                end
                else begin
                    if (start_gen[i]) begin
                        start_gen[i] <= 0;
                        radicand_gen[i] <= radicand_gen[i] >> 1;
                        root_gen[i] <= 0;
                        mask_gen[i] <= 1;
                    end
                    else begin
                        if (mask_gen[i]) begin
                            if (mask_gen[i] == 1) begin
                                if (radicand_gen[i] >= mask_gen[i]) begin
                                    root_gen[i] <= root_gen[i] + mask_gen[i];
                                    radicand_gen[i] <= radicand_gen[i] - mask_gen[i];
                                end
                                else begin
                                    radicand_gen[i] <= radicand_gen[i] << 1;
                                    mask_gen[i] <= mask_gen[i] << 1;
                                end
                            end
                            else begin
                                radicand_gen[i] <= radicand_gen[i] << 1;
                                mask_gen[i] <= mask_gen[i] << 1;
                            end
                        end
                        else begin
                            radicand_gen[i] <= radicand_gen[i] << 1;
                            mask_gen[i] <= mask_gen[i] << 1;
                        end
                    end
                end
            end
        end
    endgenerate

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            data_valid <= 0;
            root <= 0;
        end
        else begin
            if (start) begin
                data_valid <= 0;
                root <= 0;
            end
            else begin
                if (mask_gen[PIPE_STAGES-1]) begin
                    data_valid <= 1;
                    root <= root_gen[PIPE_STAGES-1];
                end
                else begin
                    data_valid <= 0;
                    root <= 0;
                end
            end
        end
    end

endmodule

