module pingpongmem(clk, rst, wren, rden, address1, address2,
                    datain, dataout, inputsize);
input clk,rst;
input wren, rden;
input [31:0] inputsize;
input [31:0] address1, address2;

input [64*16-1:0] datain;
output reg [16*16-1:0] dataout;
reg [16*16-1:0] datamem [0:64*16-1];
reg [16*16-1:0] datainmem;
reg [16*16-1:0] dataoutmem;

always @(posedge clk)
begin
    if (rst)
    begin
        datainmem <= 0;
        dataoutmem <= 0;
    end
    else if (wren)
    begin
        datainmem <= datain;
        dataoutmem <= datainmem;
    end
    else if (rden)
    begin
        dataoutmem <= datamem[address2];
    end
end

always @(dataoutmem)
begin
    dataout <= dataoutmem;
end

always @(datamem)
begin
    datamem[address1] <= datainmem;
    datamem[address1+inputsize] <= datainmem;
end

endmodule

