				4'b1000: begin
					Found <= KeyPresses[3];
					OnesDigit <= KeyPresses[3:0];
					TensDigit <= KeyPresses[7:4];
				end
				default: begin
					Found <= 0;
					OnesDigit <= 0;
					TensDigit <= 0;
				end
			endcase
		end
	end
