reg signed [IN_WIDTH-1:0] b_reg;
reg signed [ACCUM_WIDTH-1:0] ad_reg;
reg signed [ACCUM_WIDTH-1:0] m_reg;
reg signed [ACCUM_WIDTH-1:0] p_reg;
always @(posedge clk) begin
  if (clear) begin
    a_reg <= 0;
    b_reg <= 0;
    ad_reg <= 0;
    m_reg <= 0;
    p_reg <= 0;
  end
  else if (reset) begin
    a_reg <= 0;
    b_reg <= 0;
    ad_reg <= 0;
    m_reg <= 0;
    p_reg <= 0;
  end
  else if (sample_in_stb) begin
    a_reg <= sample_in_a;
    b_reg <= sample_in_b;
  end
  else if (coeff_load_stb) begin
    m_reg <= coeff_in;
  end
  else begin
    ad_reg <= a_reg + b_reg;
    m_reg <= m_reg + coeff_in;
    p_reg <= ad_reg * m_reg;
  end
