reg signed	[A_WIDTH+B_WIDTH-1:0]	r_b_1P;
reg signed	[A_WIDTH+B_WIDTH-1:0]	r_q_P[LATENCY-1:0];

always @(posedge arst or posedge clk)
begin
	if (arst)
		r_a_1P	<= 0;
	else
		r_a_1P	<= a;
end

always @(posedge arst or posedge clk)
begin
	if (arst)
		r_b_1P	<= 0;
	else
		r_b_1P	<= b;
end

always @(posedge arst or posedge clk)
begin
	if (arst)
		r_q_P[0]	<= 0;
	else
		r_q_P[0]	<= r_a_1P * r_b_1P;
end

generate
	if (LATENCY > 1)
		begin
			genvar	i;
			for (i=1; i<LATENCY; i=i+1)
				begin: mult_a_signed_b_signed_pipe
					always @(posedge arst or posedge clk)
					begin
						if (arst)
							r_q_P[i]	<= 0;
						else
							r_q_P[i]	<= r_q_P[i-1];
					end
				end
		end
		else
			begin: mult_a_signed_b_signed_pipe
				always @(posedge arst or posedge clk)
				begin
					if (arst)
						r_q_P[0]	<= 0;
					else
						r_q_P[0]	<= r_a_1P * r_b_1P;
				end
			end
endgenerate

assign o	= r_q_P[LATENCY-1];

endmodule

