module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);
reg [3*NBITS-1:0] rdata0;
  reg [3*NBITS-1:0] rdata1;
  reg [3*NBITS-1:0] rdata2;
  reg [3*NBITS-1:0] rdata3;
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      rdata0 <= 0;
      rdata1 <= 0;
      rdata2 <= 0;
      rdata3 <= 0;
    end
    else if (valid_rd) begin
      rdata0 <= rdata[0 : NUM_RDATA/4];
      rdata1 <= rdata[NUM_RDATA/4 + 1 : NUM_RDATA/2];
      rdata2 <= rdata[NUM_RDATA/2 + 1 : 3*NUM_RDATA/4];
      rdata3 <= rdata[3*NUM_RDATA/4 + 1 : NUM_RDATA];
    end
  end
  assign hrdata = rdata0 | rdata1 | rdata2 | rdata3;
endmodule

