endmodule

module ASYNC_ROM(q, addr);

  input  [AWIDTH-1:0] addr; 
  output [DWIDTH-1:0] q;
parameter DWIDTH = 16;
  parameter AWIDTH = 16;
  parameter MIF_HEX = "";
  parameter MIF_BIN = "";
  parameter DEPTH = 2**AWIDTH;

  reg [DWIDTH-1:0] mem [0:DEPTH-1];

  initial begin
    if (MIF_HEX != "") begin
      $readmemh(MIF_HEX, mem);
    end else if (MIF_BIN != "") begin
      $readmemb(MIF_BIN, mem);
    end else begin
      integer i;
      for (i = 0; i < DEPTH; i = i + 1) begin
        mem[i] = 0;
      end
    end
  end

  assign q = mem[addr];

endmodule

