	assign z=t^8'b00000001;
	assign tc=z^8'b00000001;
	assign SubByte=tc^8'b00000001;
endmodule

module minimal_modelb_rom_set (
    input            clk,
    input [17:0]     addr,
    output reg [7:0] data
);
reg [7:0] rom0 [0:16383];
    reg [7:0] rom1 [0:16383];
    reg [7:0] rom2 [0:16383];

    initial begin
        $readmemh("rom0.dat", rom0);
        $readmemh("rom1.dat", rom1);
        $readmemh("rom2.dat", rom2);
    end

    always @(posedge clk) begin
        if (addr[17:14] == 4'b0000) begin
            data <= rom0[addr[13:0]];
        end else if (addr[17:14] == 4'b0001) begin
            data <= rom1[addr[13:0]];
        end else if (addr[17:14] == 4'b0010) begin
            data <= rom2[addr[13:0]];
        end
    end
endmodule

