module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
parameter CLK_FREQ = 100000000;
  parameter UART_BPS = 115200;
  parameter BPS_CNT = CLK_FREQ / UART_BPS;
  reg [31:0] clk_cnt;
  reg [31:0] tx_cnt;
  reg [7:0] tx_data;
  reg tx_flag;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      clk_cnt <= 0;
      tx_cnt <= 0;
      tx_flag <= 0;
      tx_data <= 0;
      uart_txd <= 0;
    end else begin
      if (clk_cnt == BPS_CNT - 1) begin
        clk_cnt <= 0;
        if (tx_flag == 0) begin
          tx_flag <= 1;
          tx_data <= uart_din;
          tx_cnt <= 0;
        end else begin
          if (tx_cnt == 8) begin
            tx_cnt <= 0;
            uart_txd <= 1;
          end else begin
            tx_cnt <= tx_cnt + 1;
            uart_txd <= tx_data[tx_cnt];
          end
        end
      end else begin
        clk_cnt <= clk_cnt + 1;
      end
    end
  end
endmodule

