module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);
generate
    if (ASYNC == 0) begin : sync_mode
        reg [DATA_WIDTH-1:0] dout_reg;
        always @(posedge clk) begin
            dout_reg <= din << SHIFT_VALUE;
        end
        assign dout = dout_reg;
        assign warning = (OVERFLOW_WARNING == 1) ? (din[DATA_WIDTH-1] && (din << SHIFT_VALUE) > (2**DATA_WIDTH-1)) ? 2'b11 : (din[DATA_WIDTH-1] && (din << SHIFT_VALUE) < (2**DATA_WIDTH-1)) ? 2'b01 : 2'b00 : 2'b00;
    end else begin : async_mode
        wire [DATA_WIDTH-1:0] dout_comb;
        assign dout_comb = din << SHIFT_VALUE;
        assign dout = dout_comb;
        assign warning = (OVERFLOW_WARNING == 1) ? (DATA_TYPE == "signed" && (din[DATA_WIDTH-1] && (din << SHIFT_VALUE) > (2**DATA_WIDTH-1)) ? 2'b11 : (din[DATA_WIDTH-1] && (din << SHIFT_VALUE) < (2**DATA_WIDTH-1)) ? 2'b01 : 2'b00)) ? 2'b01 : (DATA_TYPE == "unsigned" && (din[DATA_WIDTH-1] && (din << SHIFT_VALUE) > (2**DATA_WIDTH-1)) ? 2'b11 : 2'b00) ? 2'b11 : 2'b00 : 2'b00;
    end
endgenerate

endmodule

