module alu_32 (
  input_a,
  input_b,
  control,
  zero, 
  cout,
  err_overflow,
  err_invalid_control,
  result
); 

input wire [WORD_SIZE-1:0]	input_a;
input wire [WORD_SIZE-1:0]	input_b;
input wire [CONTROL_SIGNAL_SIZE-1:0]	control;
output wire       zero;
output reg	      cout;
output reg	      err_overflow;
output reg	      err_invalid_control;
output reg [WORD_SIZE-1:0]	result;
parameter WORD_SIZE = 32;
parameter CONTROL_SIGNAL_SIZE = 4;
parameter AND = 4'b0000;
parameter OR = 4'b0001;
parameter ADD = 4'b0010;
parameter ADD_UNSIGNED = 4'b0011;
parameter SUB = 4'b0100;
parameter SLT = 4'b0101;
parameter NOR = 4'b1100;

always @(*) begin
  case (control)
    AND: begin
      result = input_a & input_b;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    OR: begin
      result = input_a | input_b;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    ADD: begin
      if (input_a[WORD_SIZE-1] == input_b[WORD_SIZE-1]) begin
        if (input_a < input_b) begin
          result = input_a + input_b;
          cout = 1;
          err_overflow = 0;
          err_invalid_control = 0;
        end
        else begin
          result = input_a + input_b;
          cout = 0;
          err_overflow = 1;
          err_invalid_control = 0;
        end
      end
      else begin
        result = input_a + input_b;
        cout = 0;
        err_overflow = 1;
        err_invalid_control = 0;
      end
    end
    ADD_UNSIGNED: begin
      if (input_a[WORD_SIZE-1] == input_b[WORD_SIZE-1]) begin
        if (input_a < input_b) begin
          result = input_a + input_b;
          cout = 1;
          err_overflow = 0;
          err_invalid_control = 0;
        end
        else begin
          result = input_a + input_b;
          cout = 0;
          err_overflow = 1;
          err_invalid_control = 0;
        end
      end
      else begin
        result = input_a + input_b;
        cout = 0;
        err_overflow = 1;
        err_invalid_control = 0;
      end
    end
    SUB: begin
      if (input_a[WORD_SIZE-1] == input_b[WORD_SIZE-1]) begin
        if (input_a > input_b) begin
          result = input_a - input_b;
          cout = 1;
          err_overflow = 0;
          err_invalid_control = 0;
        end
        else begin
          result = input_a - input_b;
          cout = 0;
          err_overflow = 1;
          err_invalid_control = 0;
        end
      end
      else begin
        result = input_a - input_b;
        cout = 0;
        err_overflow = 1;
        err_invalid_control = 0;
      end
    end
    SLT: begin
      if (input_a[WORD_SIZE-1] == input_b[WORD_SIZE-1]) begin
        if (input_a < input_b) begin
          result = 1;
          cout = 1;
          err_overflow = 0;
          err_invalid_control = 0;
        end
        else begin
          result = 0;
          cout = 0;
          err_overflow = 0;
          err_invalid_control = 0;
        end
      end
      else begin
        result = 0;
        cout = 0;
        err_overflow = 1;
        err_invalid_control = 0;
      end
    end
    NOR: begin
      result = ~(input_a | input_b);
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    default: begin
      result = 0;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 1;
    end
  endcase
end

assign zero = (result == 0);

endmodule

