reg [23:0] allowed_cycles_reg;
reg [23:0] allowed_cycles_next;
reg [15:0] height_reg;
reg [15:0] height_next;
reg [15:0] width_reg;
reg [15:0] width_next;
wire clk = full_clk;
wire rst = full_rst;
always @(posedge clk or posedge rst) begin
	if (rst) begin
		allowed_cycles_reg <= 24'h65b710;
		height_reg <= 16'h0c00;
		width_reg <= 16'h1000;
	end else begin
		allowed_cycles_reg <= allowed_cycles_next;
		height_reg <= height_next;
		width_reg <= width_next;
	end
end
always @(*) begin
	if (rst) begin
		allowed_cycles_next = 24'h65b710;
		height_next = 16'h0c00;
		width_next = 16'h1000;
	end else begin
		allowed_cycles_next = allowed_cycles_reg;
		height_next = height_reg;
		width_next = width_reg;
	end
end
assign allowed_cycles = allowed_cycles_reg;
assign height = height_reg;
assign width = width_reg;
endmodule

