module pwm#(
	    parameter WAVE_WEIGHT=1024, 
	    parameter WAVE_LEN_WIDTH = 11 
	    )
    (
     input wire clk,
     input wire reset,


     input wire update,
     input wire [WAVE_LEN_WIDTH-1:0] wave_length,
     input wire [WAVE_LEN_WIDTH-1:0] pulse_width,
     input wire active_high,

     output wire [WAVE_LEN_WIDTH-1:0] wave_length_out,
     output wire [WAVE_LEN_WIDTH-1:0] pulse_width_out,
     output wire active_high_out,

     input wire enable,
     output wire pwm_out
     );
reg [WAVE_LEN_WIDTH-1:0] wave_length_reg;
    reg [WAVE_LEN_WIDTH-1:0] pulse_width_reg;
    reg active_high_reg;

    reg [WAVE_LEN_WIDTH-1:0] wave_length_counter;
    reg [WAVE_LEN_WIDTH-1:0] pulse_width_counter;
    reg active_high_counter;

    reg pwm_reg;

    assign wave_length_out = wave_length_reg;
    assign pulse_width_out = pulse_width_reg;
    assign active_high_out = active_high_reg;
    assign pwm_out = pwm_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            wave_length_reg <= 0;
            pulse_width_reg <= 0;
            active_high_reg <= 0;
            wave_length_counter <= 0;
            pulse_width_counter <= 0;
            active_high_counter <= 0;
            pwm_reg <= 0;
        end
        else begin
            if (update) begin
                wave_length_reg <= wave_length;
                pulse_width_reg <= pulse_width;
                active_high_reg <= active_high;
            end
            if (enable) begin
                if (wave_length_counter == wave_length_reg) begin
                    wave_length_counter <= 0;
                    if (pulse_width_counter == pulse_width_reg) begin
                        pulse_width_counter <= 0;
                        if (active_high_counter == active_high_reg) begin
                            active_high_counter <= 0;
                            pwm_reg <= 1;
                        end
                        else begin
                            pwm_reg <= 0;
                            active_high_counter <= active_high_counter + 1;
                        end
                    end
                    else begin
                        pulse_width_counter <= pulse_width_counter + 1;
                    end
                end
                else begin
                    wave_length_counter <= wave_length_counter + 1;
                end
            end
            else begin
                pwm_reg <= 0;
            end
        end
    end

endmodule

module dffeas (d, clk, ena, clrn, prn, aload, asdata, sclr, sload, devclrn, devpor, q );

input d;
input clk;
input ena;
input clrn;
input prn;
input aload; 
input asdata;  
input sclr; 
input sload; 
input devclrn; 
input devpor; 

output q;
reg q_tmp;
reg q_tmp_dly;
reg d_viol;
reg sclr_viol;
reg sload_viol;
reg aload_viol;
reg prn_viol;
reg clrn_viol;
reg ena_viol;
reg reset;
reg asdata_dly;

wire resetn = ~reset;
wire asdata_dlyn = ~asdata_dly;
wire d_violn = ~d_viol;
wire sclr_violn = ~sclr_viol;
wire sload_violn = ~sload_viol;
wire aload_violn = ~aload_viol;
wire prn_violn = ~prn_viol;
wire clrn_violn = ~clrn_viol;
wire ena_violn = ~ena_viol;

reg violation;

specify
    $setuphold (posedge clk &&& resetn, d, 0, 0, d_viol) ;
    $setuphold (posedge clk &&& resetn, sclr, 0, 0, sclr_viol) ;
    $setuphold (posedge clk &&& resetn, sload, 0, 0, sload_viol) ;
    $setuphold (posedge clk &&& resetn, aload, 0, 0, aload_viol) ;
    $setuphold (posedge clk &&& resetn, prn, 0, 0, prn_viol) ;
    $setuphold (posedge clk &&& resetn, clrn, 0, 0, clrn_viol) ;
    $setuphold (posedge clk &&& resetn, ena, 0, 0, ena_viol) ;
    (posedge clk => (q +: q_tmp)) = 0 ;
endspecify

initial
begin
    q_tmp = 1'b0;
    q_tmp_dly = 1'b0;
    d_viol = 1'b0;
    sclr_viol = 1'b0;
    sload_viol = 1'b0;
    aload_viol = 1'b0;
    prn_viol = 1'b0;
    clrn_viol = 1'b0;
    ena_viol = 1'b0;
    violation = 1'b0;
    asdata_dly = 1'b0;
    reset = 1'b0;
    sload_violn = 1'b0;
    aload_violn = 1'b0;
    prn_violn = 1'b0;
    clrn_violn = 1'b0;
    ena_violn = 1'b0;
    d_violn = 1'b0;
    sclr_violn = 1'b0;
    sload_violn = 1'b0;
    aload_violn = 1'b0;
    prn_violn = 1'b0;
    clrn_violn = 1'b0;
    ena_violn = 1'b0;
    violationn = 1'b0;
end

always @(posedge clk or negedge clrn or negedge prn )
begin
    if (clrn == 1'b0)
    begin
        violation = 1'b1;
        q_tmp <= 1'b1;
    end
    else if (prn == 1'b0)
    begin
        violation = 1'b1;
        q_tmp <= 1'b0;
    end
    else if ((ena == 1'b1) && (reset == 1'b1))
    begin
        violation = 1'b1;
        q_tmp <= 1'b0;
    end
    else if ((ena == 1'b1) && (reset == 1'b0))
    begin
        violation = 1'b1;
        q_tmp <= 1'b1;
    end
    else if ((aload == 1'b1) && (aload_violn == 1'b0))
    begin
        violation = 1'b1;
        q_tmp <= asdata_dly;
    end
    else if ((sclr == 1'b1) && (sclr_violn == 1'b0))
    begin
        violation = 1'b1;
        q_tmp <= 1'b0;
    end
    else if ((sload == 1'b1) && (sload_violn == 1'b0))
    begin
        violation = 1'b1;
        q_tmp <= 1'b1;
    end
    else if ((devclrn == 1'b0) || (devpor == 1'b0))
    begin
        violation = 1'b1;
        q_tmp <= 1'bx;
    end
    else
    begin
        violation = 1'b0;
        q_tmp <= q_tmp_dly;
    end
end

always @(posedge clk or negedge clrn or negedge prn )
begin
    if (clrn == 1'b0)
    begin
        q_tmp_dly <= 1'b1;
    end
    else if (prn == 1'b0)
    begin
        q_tmp_dly <= 1'b0;
    end
    else if ((ena == 1'b1) && (reset == 1'b1))
    begin
        q_tmp_dly <= 1'b0;
    end
    else if ((ena == 1'b1) && (reset == 1'b0))
    begin
        q_tmp_dly <= 1'b1;
    end
    else if ((aload == 1'b1) && (aload_violn == 1'b0))
    begin
        q_tmp_dly <= asdata_dly;
    end
    else if ((sclr == 1'b1) && (sclr_violn == 1'b0))
    begin
        q_tmp_dly <= 1'b0;
    end
    else if ((sload == 1'b1) && (sload_violn == 1'b0))
    begin
        q_tmp_dly <= 1'b1;
    end
    else if ((devclrn == 1'b0) || (devpor == 1'b0))
    begin
        q_tmp_dly <= 1'bx;
    end
    else
    begin
        q_tmp_dly <= q_tmp;
    end
end

and (q, q_tmp, 1'b1);

endmodule

module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg[3:0] cnt;
    always@(posedge clk or posedge reset)
    begin
        if(reset)
            cnt<=0;
        else
            cnt<=cnt+1;
    end
    always@(cnt)
    begin
        case(cnt)
            0:en<=4'b1000;
            1:en<=4'b0100;
            2:en<=4'b0010;
            3:en<=4'b0001;
            default:en<=4'b0000;
        endcase
    end
    always@(hex3 or hex2 or hex1 or hex0)
    begin
        case({hex3,hex2,hex1,hex0})
            4'h0:sseg<=8'b0000001;
            4'h1:sseg<=8'b1001111;
            4'h2:sseg<=8'b0010010;
            4'h3:sseg<=8'b0000110;
            4'h4:sseg<=8'b1001100;
            4'h5:sseg<=8'b0100100;
            4'h6:sseg<=8'b0100000;
            4'h7:sseg<=8'b0001111;
            4'h8:sseg<=8'b0000000;
            4'h9:sseg<=8'b0000100;
            4'ha:sseg<=8'b0001000;
            4'hb:sseg<=8'b0000010;
            4'hc:sseg<=8'b0000111;
            4'hd:sseg<=8'b0001001;
            4'he:sseg<=8'b0000000;
            4'hf:sseg<=8'b0000100;
            default:sseg<=8'b0000000;
        endcase
    end
    always@(dp)
    begin
        case(dp)
