wire shiftnld_ipd;
wire captnupdt_ipd;

buf buf_clk (clk_ipd, clk);
buf buf_shiftnld (shiftnld_ipd, shiftnld);
buf buf_captnupdt (captnupdt_ipd, captnupdt);

assign clk = clk_ipd;
assign shiftnld = shiftnld_ipd;
assign captnupdt = captnupdt_ipd;

initial
begin
    mainclk_tmp = 0;
    updateclk_tmp = 0;
    capture_tmp = 0;
    update_tmp = 0;
    clk_last_value = 0;
end

always @(captnupdt_ipd or shiftnld_ipd or clk_ipd)
begin
    if (clk_last_value === 1'b0)
    begin
        case ({captnupdt_ipd, shiftnld_ipd})
            2'b10: 
            begin
                mainclk_tmp = 0;
                updateclk_tmp = 0;
                capture_tmp = 1;
                update_tmp = 0;
            end
            2'b11: 
            begin
                mainclk_tmp = 0;
                updateclk_tmp = 0;
                capture_tmp = 1;
                update_tmp = 1;
            end
            2'b01: 
            begin
                mainclk_tmp = 0;
                updateclk_tmp = 0;
                capture_tmp = 0;
                update_tmp = 0;
            end
            default: 
            begin
                mainclk_tmp = 0;
                updateclk_tmp = 0;
                capture_tmp = 0;
                update_tmp = 1;
            end
        endcase
    end
    else
    begin
        case ({captnupdt_ipd, shiftnld_ipd})
            2'b10: 
            begin
                mainclk_tmp = clk_ipd;
                updateclk_tmp = clk_ipd;
                capture_tmp = 0;
                update_tmp = 0;
            end
            2'b11: 
            begin
                mainclk_tmp = clk_ipd;
                updateclk_tmp = clk_ipd;
                capture_tmp = 0;
                update_tmp = 1;
            end
            2'b01: 
            begin
                mainclk_tmp = clk_ipd;
                updateclk_tmp = clk_ipd;
                capture_tmp = 1;
                update_tmp = 0;
            end
            default: 
            begin
                mainclk_tmp = clk_ipd;
                updateclk_tmp = clk_ipd;
                capture_tmp = 0;
                update_tmp = 0;
            end
        endcase
    end
    clk_last_value = clk_ipd;
end

