module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma;
reg [31:0] delta;
reg [31:0] undersampled_sigma;
reg [31:0] deriv;

assign dout = signed_data ? -deriv : deriv;

always @(posedge clk or negedge rstn) begin
	if (!rstn) begin
		sigma <= 0;
		undersampled_sigma <= 0;
		delta <= 0;
		deriv <= 0;
	end else begin
		if (ock) begin
			sigma <= sigma + delta;
			if (sigma == 32'd127) begin
				sigma <= 32'd0;
			end
		end
		if (uck) begin
			undersampled_sigma <= sigma;
		end
		if (sigma == 32'd0) begin
			delta <= 32'd1;
		end else if (sigma == 32'd127) begin
			delta <= 32'd-1;
		end
		if (sigma == 32'd127) begin
			deriv <= 32'd0;
		end else begin
			deriv <= sigma - undersampled_sigma;
		end
	end
end

endmodule

module RegFile(
    output reg signed  [31:0] ReadData1, ReadData2,
    input [4:0] ReadReg1, ReadReg2, WriteReg,
    input signed [31:0] WriteData,
    input RegWrite, Clk
    );
reg signed [31:0] RegFile [31:0];
    always @(negedge Clk)
    begin
        if (ReadReg1 == 0)
            ReadData1 <= 0;
        else
            ReadData1 <= RegFile[ReadReg1];
        if (ReadReg2 == 0)
            ReadData2 <= 0;
        else
            ReadData2 <= RegFile[ReadReg2];
    end
    always @(posedge Clk)
    begin
        if (RegWrite)
            RegFile[WriteReg] <= WriteData;
    end
endmodule

