						if (counter[4] == 0) begin
							counter <= counter + 1;
							if (counter[4] == 0) begin
								counter <= counter + 1;
							end
						end
						else begin
							counter <= counter + 1;
						end
					end
				end
				else begin
					if (counter[24] == 0) begin
						counter <= counter + 1;
						if (counter[24] == 0) begin
							counter <= counter + 1;
						end
					end
					else begin
						counter <= counter + 1;
					end
