				readn <= 0;
			end
		end
	end

	always @(posedge clk or posedge rst) begin
		if (rst) begin
			step <= 0;
			auto_clk <= 0;
		end
		else begin
			if (wasReady) begin
				if (counter[4] == 0) begin
					step <= 0;
					auto_clk <= 0;
				end
				else begin
					step <= step + 1;
					if (step == 0) begin
						auto_clk <= 1;
					end
					else begin
						auto_clk <= 0;
					end
				end
			end
			else begin
				step <= 0;
				auto_clk <= 0;
			end
		end
	end

	assign Clk_CPU = (SW15) ? auto_clk : 1'b0;

	assign wasReady = (keyReady) ? 1'b1 : 1'b0;

endmodule

