module gray_Nbits (clk, reset, enable, gray_out);

input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter N = 4;
parameter SIZE = N+1;
parameter Zeros = {SIZE{1'b0}};

reg [SIZE-1:0] state = Zeros;
reg [SIZE-1:0] toggle = Zeros;

assign gray_out = state[SIZE-1:1];

always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= Zeros;
	else if (enable)
		state <= toggle ^ state;
end

always @(state)
begin
	toggle[0] = 1'b1;
	for (int i = 1; i < SIZE; i = i + 1)
		toggle[i] = toggle[i-1] ^ (state[i-1] & state[i]);
end

endmodule

