module dff(q, q_bar, d, clk, rst);
  output q, q_bar;
  input d, clk, rst;
reg q;
  not(q_bar, q);
  always @(posedge clk or posedge rst)
    if (rst)
      q <= 0;
    else
      q <= d;
endmodule

module MEM_BLK_V5_0( clk,
                     write_en,
                     read_en,
                     wr_addr,
                     rd_addr,
                     data_in,
                     data_out,
                     rst
                   );


input                    clk;       
input                    write_en;    
input                    read_en ;
input  [(addr_value-1):0]  wr_addr;   
input  [(addr_value-1):0]  rd_addr;   
input  [(data_width-1):0]   data_in;   
input                    rst ;

output [(data_width-1):0]   data_out;
parameter data_width = 16;
parameter addr_value = 4;
parameter mem_size = 16;

reg  [(data_width-1):0]   mem [0:mem_size-1];
reg  [(data_width-1):0]   data_out;

always @ (posedge clk)
begin
    if (rst)
    begin
        data_out <= {data_width{1'b0}};
    end
    else if (read_en)
    begin
        data_out <= mem[rd_addr];
    end
    else if (write_en)
    begin
        mem[wr_addr] <= data_in;
    end
end

endmodule

