module hardcopyiv_pciehip_pciexp_dcram_rtry (
   wrclock,
   wren,
   wraddress,
   data,
   rdclock,
   rdaddress,
   q
   );

	input   wrclock; 
	input   wren; 
	input   [data_width - 1:0] data; 
	input   [addr_width - 1:0] wraddress; 
	input	rdclock;
	input   [addr_width - 1:0] rdaddress; 
	output  [data_width - 1:0] q;
parameter addr_width = 10; 
parameter data_width = 16; 
	reg    [data_width - 1:0] ram[2**addr_width - 1:0]; 
	reg    [addr_width - 1:0] rdaddress_reg; 
	reg    [data_width - 1:0] wrdata_reg; 
	wire   [addr_width - 1:0] wraddress; 
	wire   [data_width - 1:0] data; 
	wire   wren; 
	wire   wrclock; 
	wire   rdclock; 
	reg    [addr_width - 1:0] rdaddress_reg_prev; 
	reg    [data_width - 1:0] wrdata_reg_prev; 
	reg    [data_width - 1:0] ram[2**addr_width - 1:0]; 


	always @ (posedge wrclock)
	  begin
	     if (wren == 1'b1)
	       begin
	          wrdata_reg <= data; 
	          ram[wraddress] <= wrdata_reg; 
	       end
	  end


	always @ (posedge rdclock)
	  begin
	     if (rdaddress_reg_prev != rdaddress_reg)
	       begin
	          rdaddress_reg <= rdaddress_reg_prev; 
	       end
	     rdaddress_reg_prev <= rdaddress_reg; 
	  end


	always @ (posedge rdclock)
	  begin
	     if (rdaddress_reg_prev != rdaddress_reg)
	       begin
	          wrdata_reg_prev <= wrdata_reg; 
	       end
	     wrdata_reg_prev <= wrdata_reg; 
	  end


	assign q = ram[rdaddress_reg]; 


endmodule

