module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter DATA_WIDTH = 32;
parameter INSERT_REGISTER = 0;

 generate
  if (INSERT_REGISTER == 1) begin
    reg [DATA_WIDTH-1:0] datain_reg;
    reg datain_reg_valid;
    reg datain_reg_stall;
    reg datain_reg_valid_stall;
    always @(posedge clock or negedge resetn) begin
      if (!resetn) begin
        datain_reg <= {DATA_WIDTH{1'b0}};
        datain_reg_valid <= 1'b0;
        datain_reg_stall <= 1'b0;
        datain_reg_valid_stall <= 1'b0;
      end
      else begin
        datain_reg <= i_datain;
        datain_reg_valid <= i_datain_valid;
        datain_reg_stall <= i_datain_valid & i_datain_stall;
        datain_reg_valid_stall <= i_datain_valid & i_datain_stall;
      end
    end
    always @(posedge clock or negedge resetn) begin
      if (!resetn) begin
        o_datain_stall <= 1'b0;
        o_dataout_valid <= 1'b0;
        o_dataout <= {DATA_WIDTH{1'b0}};
      end
      else begin
        o_datain_stall <= datain_reg_stall;
        o_dataout_valid <= datain_reg_valid_stall;
        o_dataout <= datain_reg;
      end
    end
  end
  else begin
    always @(i_datain, i_datain_valid, i_datain_stall, i_dataout_stall, i_dataout_valid) begin
      o_datain_stall <= i_datain_valid & i_datain_stall;
      o_dataout_valid <= i_datain_valid & i_datain_stall;
      o_dataout <= i_datain;
    end
  end
 endgenerate

endmodule

