module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
parameter Divider = 100000;
reg [26:0] counter;
always @(counter)
begin
	if (counter == Divider)
		Timeout = 1;
	else
		Timeout = 0;
end
always @(posedge Clock)
begin
	if (MR)
		counter <= 0;
	else if (counter == Divider)
		counter <= 0;
	else
		counter <= counter + 1;
end
endmodule

