module Incer #(
    parameter DATA_WIDTH = 8
)
(clk,arstn,din,dout,mode);

input clk;
input arstn;
input mode;
input [DATA_WIDTH-1:0]din;
output [DATA_WIDTH-1:0]dout;
reg [DATA_WIDTH-1:0]counter;
reg [1:0]state;

parameter ADD_STATE = 0;
parameter INC_STATE = 1;

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        counter <= 0;
        state <= ADD_STATE;
    end
    else
    begin
        case(state)
            ADD_STATE:begin
                if(mode)
                begin
                    if(counter == 0)
                    begin
                        counter <= 1;
                        state <= INC_STATE;
                    end
                    else
                    begin
                        counter <= counter + 1;
                    end
                end
                else
                begin
                    state <= ADD_STATE;
                end
            end
            INC_STATE:begin
                if(counter == 0)
                begin
                    counter <= 1;
                    state <= INC_STATE;
                end
                else
                begin
                    counter <= counter + 1;
                end
            end
        endcase
    end
end

assign dout = counter;

endmodule

