module Control(
		input clk,
		input start,
		output[3:0] direction,
		output ready
	);
reg[2:0] state;
	always @(posedge clk or posedge start)
		if(start)
			state <= 3'b000;
		else
			state <= state + 3'b001;
	assign direction = state[2] ? 4'b0001 : state[1] ? 4'b0010 : state[0] ? 4'b0100 : 4'b1000;
	assign ready = state[2] | state[1] | state[0];
endmodule

