reg [9:0] in;
wire [3:0] ones;
wire [3:0] tens;
wire [3:0] hundreds;
wire thousands;

binary_to_BCD_ten_bit uut(.in(in), .ones(ones), .tens(tens), .hundreds(hundreds), .thousands(thousands));

initial begin
    $display("in\tones tens hundreds thousands");
    $display("---- ---- ---- ---- ----");
    in = 0;
    repeat (1023) begin
        #1;
        $display("%d\t%4b %4b %4b %b", in, ones, tens, hundreds, thousands);
        in = in + 1;
    end
end

endmodule

module FullAdder(
  input wire a, 
  input wire b,
  input wire carry_in,
  output wire sum,
  output wire carry_out
);
assign sum = a ^ b;
  assign carry_out = (a & b) | (carry_in & sum);
endmodule

module AOI31X1TS (Y, A0, A1, A2, B0);
output Y;
input A0, A1, A2, B0;
and I0(outA, A0, A1, A2);
  nor I1(Y, B0, outA);

  specify

    specparam
      tplh$A0$Y = 1.0,
      tphl$A0$Y = 1.0,
      tplh$A1$Y = 1.0,
      tphl$A1$Y = 1.0,
      tplh$A2$Y = 1.0,
      tphl$A2$Y = 1.0,
      tplh$B0$Y = 1.0,
      tphl$B0$Y = 1.0;


    if (A1 == 1'b1 && A2 == 1'b1)
       (B0 *> Y) = (tplh$B0$Y, tphl$B0$Y);
    if (A0 == 1'b1 && A2 == 1'b1)
       (B0 *> Y) = (tplh$B0$Y, tphl$B0$Y);
    if (A0 == 1'b1 && A1 == 1'b1)
       (B0 *> Y) = (tplh$B0$Y, tphl$B0$Y);
    if (A0 == 1'b0 && A1 == 1'b0)
       (B0 *> Y) = (tplh$B0$Y, tphl$B0$Y);
    if (A0 == 1'b0 && A1 == 1'b1)
       (B0 *> Y) = (tplh$B0$Y, tphl$B0$Y);
    if (A0 == 1'b1 && A1 == 1'b0)
       (B0 *> Y) = (tplh$B0$Y, tphl$B0$Y);
  endspecify
endmodule

