module button_pulse 
#(
    parameter MAX_COUNT = 8,    
    parameter DEC_COUNT = 2,    
    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);
reg [MAX_COUNT-1:0] comp;
    reg [MAX_COUNT-1:0] count;
    assign pulse = (count == 0) & button;
    always @(posedge clk) begin
        if (reset) begin
            comp <= MAX_COUNT - 1;
            count <= 0;
        end
        else if (clk_en) begin
            if (button) begin
                if (count == 0) begin
                    if (comp == 0) begin
                        comp <= MAX_COUNT - 1;
                        count <= count + 1;
                    end
                    else begin
                        comp <= comp - DEC_COUNT;
                        count <= count + 1;
                    end
                end
                else begin
                    count <= count + 1;
                end
            end
            else begin
                count <= 0;
            end
        end
    end
endmodule

