module gh_delay_programmable_31(
input wire CLK,
input wire rst,
input wire srst,
input wire D,
input wire [4:0] DELAY,
output wire Q
); 

wire [4:0] DELAY_1;
wire [4:0] DELAY_2;
wire [4:0] DELAY_4;
wire [4:0] DELAY_8;
wire [4:0] DELAY_16;
wire D_d1;
wire D_d2;
wire D_d4;
wire D_d8;
wire D_d16;
wire Q_d1;
wire Q_d2;
wire Q_d4;
wire Q_d8;
wire Q_d16;
  assign DELAY_1 = DELAY;
  assign DELAY_2 = DELAY_1 + 1;
  assign DELAY_4 = DELAY_2 + 1;
  assign DELAY_8 = DELAY_4 + 1;
  assign DELAY_16 = DELAY_8 + 1;
  gh_delay #(
      .DELAY(DELAY_1))
  gh_delay_1(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D),
    .Q(D_d1));
  gh_delay #(
      .DELAY(DELAY_2))
  gh_delay_2(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D_d1),
    .Q(D_d2));
  gh_delay #(
      .DELAY(DELAY_4))
  gh_delay_4(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D_d2),
    .Q(D_d4));
  gh_delay #(
      .DELAY(DELAY_8))
  gh_delay_8(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D_d4),
    .Q(D_d8));
  gh_delay #(
      .DELAY(DELAY_16))
  gh_delay_16(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D_d8),
    .Q(D_d16));
  assign Q_d1 = D;
  assign Q_d2 = D_d1;
  assign Q_d4 = D_d2;
  assign Q_d8 = D_d4;
  assign Q_d16 = D_d8;
  assign Q = DELAY[0] == 1'b1 ? D_d1 : DELAY[1] == 1'b1 ? D_d2 : DELAY[2] == 1'b1 ? D_d4 : DELAY[3] == 1'b1 ? D_d8 : DELAY[4] == 1'b1 ? D_d16 : D;
endmodule

