    end
    4'b0010 : begin
      decOut_n <= 7'b1001111;
    end
    4'b0011 : begin
      decOut_n <= 7'b0010010;
    end
    4'b0100 : begin
      decOut_n <= 7'b0000110;
    end
    4'b0101 : begin
      decOut_n <= 7'b1001100;
    end
    4'b0110 : begin
      decOut_n <= 7'b0100100;
    end
    4'b0111 : begin
      decOut_n <= 7'b0100000;
    end
    4'b1000 : begin
      decOut_n <= 7'b0001111;
    end
    4'b1001 : begin
      decOut_n <= 7'b0000000;
    end
    default : begin
      decOut_n <= 7'b1000000;
    end
    endcase
  end
endmodule

