module testbench;
reg [2:0] A, B;
wire A_greater, A_equal, A_less;

comparator_3bit cmp(A_greater, A_equal, A_less, A, B);

integer i, error = 0;

initial begin
    for (i = 0; i < 100; i = i + 1) begin
        A = $random;
        B = $random;
        if (A_greater !== (A > B)) begin
            $display("Failed at time %d, A = %d, B = %d, A_greater = %d, A_equal = %d, A_less = %d", $time, A, B, A_greater, A_equal, A_less);
            error = error + 1;
        end
        if (A_equal !== (A == B)) begin
            $display("Failed at time %d, A = %d, B = %d, A_greater = %d, A_equal = %d, A_less = %d", $time, A, B, A_greater, A_equal, A_less);
            error = error + 1;
        end
        if (A_less !== (A < B)) begin
            $display("Failed at time %d, A = %d, B = %d, A_greater = %d, A_equal = %d, A_less = %d", $time, A, B, A_greater, A_equal, A_less);
            error = error + 1;
        end
    end
    if (error == 0) begin
        $display("=========== Your Design Passed ===========");
    end else begin
        $display("=========== Test completed with %d /100 failures ===========", error);
    end
    $finish;
end

endmodule

