module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );
localparam [31:0] SEED = 32'h00000000;


  reg [31:0] M_x, M_y, M_z, M_w;
  reg [31:0] M_w_d;
  wire [31:0] M_x_q = M_x;
  wire [31:0] M_y_q = M_y;
  wire [31:0] M_z_q = M_z;
  wire [31:0] M_w_q = M_w;
  wire [31:0] t = M_x_q & M_y_q;

  always @* begin
    M_w_d = M_w_q;
    M_x = M_x_q;
    M_y = M_y_q;
    M_z = M_z_q;
    M_w = M_w_q;

    if (next) begin
      M_x = M_x_q << 1;
      M_x[0] = M_x_q[31];
      M_y = M_y_q << 1;
      M_y[0] = M_y_q[31];
      M_z = M_z_q << 1;
      M_z[0] = M_z_q[31];
      M_w = M_w_q << 1;
      M_w[0] = M_w_q[31];
      M_w_d = M_w_q ^ t;
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      M_w <= SEED;
    end else begin
      M_w <= M_w_d;
    end
  end

  always @(posedge clk) begin
    num <= M_w_q;
  end

endmodule

