module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg [2:0] state; 

always @(posedge clk or posedge reset)
begin
if(reset)
state <= 3'b000;
else
case(state)
3'b000: state <= 3'b001;
3'b001: state <= 3'b010;
3'b010: state <= 3'b011;
3'b011: state <= 3'b100;
3'b100: state <= 3'b101;
3'b101: state <= 3'b110;
3'b110: state <= 3'b111;
3'b111: state <= 3'b000;
endcase
end
assign red = (state == 3'b000) ? 1'b1 : 1'b0;
assign yellow = (state == 3'b001) ? 1'b1 : 1'b0;
assign green = (state == 3'b010) ? 1'b1 : 1'b0;
endmodule

