module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);
parameter IDLE = 2'b00;
   parameter SETUP = 2'b01;
   parameter ACCESS = 2'b10;
   reg [1:0] state;
   always @(posedge PCLK or negedge PRESETn) begin
      if (!PRESETn) begin
         state <= IDLE;
      end
      else begin
         case (state)
            IDLE: begin
               if (PREADY) begin
                  if (PSELx) begin
                     PSELx <= 0;
                     PENABLE <= 0;
                     PWRITE <= 0;
                     PADDR <= Address;
                     PWDATA <= write_data;
                     if (Wr_Rd) begin
                        PSELx <= 1;
                        PENABLE <= 1;
                        PWRITE <= 1;
                        PADDR <= Address;
                        PWDATA <= write_data;
                     end
                     else begin
                        PSELx <= 0;
                        PENABLE <= 0;
                        PWRITE <= 0;
                        PADDR <= Address;
                        PWDATA <= write_data;
                     end
                  end
                  else begin
                     PSELx <= 0;
                     PENABLE <= 0;
                     PWRITE <= 0;
                     PADDR <= Address;
                     PWDATA <= write_data;
                  end
               end
               else begin
                  PSELx <= 0;
                  PENABLE <= 0;
                  PWRITE <= 0;
                  PADDR <= Address;
                  PWDATA <= write_data;
               end
            end
            SETUP: begin
               if (PREADY) begin
                  PSELx <= 0;
                  PENABLE <= 0;
                  PWRITE <= 0;
                  PADDR <= Address;
                  PWDATA <= write_data;
               end
               else begin
                  PSELx <= 0;
                  PENABLE <= 0;
                  PWRITE <= 0;
                  PADDR <= Address;
                  PWDATA <= write_data;
               end
            end
            ACCESS: begin
               if (PREADY) begin
                  PSELx <= 0;
                  PENABLE <= 0;
                  PWRITE <= 0;
                  PADDR <= Address;
                  PWDATA <= write_data;
               end
               else begin
                  PSELx <= 0;
                  PENABLE <= 0;
                  PWRITE <= 0;
                  PADDR <= Address;
                  PWDATA <= write_data;
               end
            end
         endcase
      end
   end
   always @(posedge PCLK or negedge PRESETn) begin
      if (!PRESETn) begin
         read_data <= 0;
      end
      else begin
         if (state == IDLE) begin
            read_data <= 0;
         end
         else if (state == ACCESS) begin
            read_data <= PRDATA;
         end
         else begin
            read_data <= 0;
         end
      end
   end
endmodule

