module KEY_MUX
(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);
reg [3:0]S, NS;
reg [7:0]in1, in2, in3, out;
wire [7:0]scan_code;
keyboard keyboard(.clk(PS2_CLK), .dat(PS2_DAT), .scan_code(scan_code));
display display(.clk(PS2_CLK), .data(in1), .display(HEX0));
display display2(.clk(PS2_CLK), .data(in2), .display(HEX1));
display display3(.clk(PS2_CLK), .data(in3), .display(HEX1));
assign LEDR[3:0] = S;
assign LEDR[9:4] = NS;
always @(scan_code)
begin
	NS = S;
	case(S)
		4'b0000: begin
			in1 = scan_code;
			NS = 4'b0001;
		end
		4'b0001: begin
			in2 = scan_code;
			NS = 4'b0010;
		end
		4'b0010: begin
			in3 = scan_code;
			NS = 4'b0011;
		end
		4'b0011: begin
			out = scan_code;
			NS = 4'b0100;
		end
		4'b0100: begin
			NS = 4'b0000;
		end
	endcase
end
endmodule

