module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 10;
    reg [maxbit-1:0] q_reg, q_next;
    reg f1, f2;
    wire q_add, q_reset;
    assign q_add = q_reg == 0;
    assign q_reset = ~q_reg[0];
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 0;
        end else begin
            q_reg <= q_next;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            f1 <= 0;
            f2 <= 0;
            out <= 0;
        end else begin
            f1 <= button_in;
            f2 <= f1;
            case (q_reg)
                0: begin
                    if (f2 == 1) begin
                        q_next <= 1;
                    end
                end
                1: begin
                    if (f2 == 0) begin
                        q_next <= 0;
                    end
                end
                default: begin
                    q_next <= 0;
                end
            endcase
            if (q_reg == 0) begin
                out <= 1;
            end else begin
                out <= 0;
            end
        end
    end
endmodule

