module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output [7 : 0] q
);
reg [7 : 0] mem [15 : 0];
    reg [3 : 0] wp, rp;
    reg w_flag, r_flag;
    always @(posedge clock or posedge sclr) begin
        if (sclr) begin
            wp <= 0;
            rp <= 0;
            w_flag <= 0;
            r_flag <= 0;
        end
        else begin
            if (wrreq) begin
                mem[wp] <= data;
                wp <= (wp + 1) % 16;
                w_flag <= 1;
            end
            if (rdreq) begin
                rp <= (rp + 1) % 16;
                r_flag <= 1;
            end
        end
    end
    always @(posedge clock or posedge sclr) begin
        if (sclr) begin
            full <= 0;
            empty <= 1;
        end
        else begin
            full <= (w_flag & (wp == rp));
            empty <= (r_flag & (wp == rp));
        end
    end
    assign q = mem[rp];
endmodule

