    input wire [31:0] clk_counter,
    input wire conv_done,
    output reg conv_start,
    output reg [2:0]  COMMAND,
    output reg [8:0]  InCh,
    output reg [8:0]  OutCh,
    output reg [5:0]  FLength,
    input wire  F_writedone,
    output reg  F_writedone_respond,
    input wire  B_writedone,
    output reg  B_writedone_respond,
    input wire  rdy_to_transmit,
    output reg  rdy_to_transmit_respond,
    input wire  transmit_done,
    output reg  transmit_done_respond 
  );
reg [31:0] conv_start_reg;
  reg [2:0] COMMAND_reg;
  reg [8:0] InCh_reg;
  reg [8:0] OutCh_reg;
  reg [5:0] FLength_reg;
  reg F_writedone_reg;
  reg B_writedone_reg;
  reg rdy_to_transmit_reg;
  reg transmit_done_reg;
  assign PRDATA = (PSEL && PENABLE && PWRITE) ? 
    (PADDR == 32'h00000000) ? conv_start_reg :
    (PADDR == 32'h00000004) ? COMMAND_reg :
    (PADDR == 32'h00000008) ? InCh_reg :
    (PADDR == 32'h00000009) ? OutCh_reg :
    (PADDR == 32'h0000000A) ? FLength_reg :
    (PADDR == 32'h0000000B) ? F_writedone_reg :
    (PADDR == 32'h0000000C) ? B_writedone_reg :
    (PADDR == 32'h0000000D) ? rdy_to_transmit_reg :
    (PADDR == 32'h0000000E) ? transmit_done_reg :
    32'h00000000;
  always @(posedge PCLK or negedge PRESETB) begin
    if (!PRESETB) begin
      conv_start_reg <= 32'h00000000;
      COMMAND_reg <= 32'h00000000;
      InCh_reg <= 32'h00000000;
      OutCh_reg <= 32'h00000000;
      FLength_reg <= 32'h00000000;
      F_writedone_reg <= 32'h00000000;
      B_writedone_reg <= 32'h00000000;
      rdy_to_transmit_reg <= 32'h00000000;
      transmit_done_reg <= 32'h00000000;
    end
    else begin
      if (PSEL && PENABLE && PWRITE) begin
        if (PADDR == 32'h00000000) begin
          conv_start_reg <= PWDATA[31:0];
        end
        else if (PADDR == 32'h00000004) begin
          COMMAND_reg <= PWDATA[2:0];
        end
        else if (PADDR == 32'h00000008) begin
          InCh_reg <= PWDATA[8:0];
        end
        else if (PADDR == 32'h00000009) begin
          OutCh_reg <= PWDATA[8:0];
        end
        else if (PADDR == 32'h0000000A) begin
          FLength_reg <= PWDATA[5:0];
        end
        else if (PADDR == 32'h0000000B) begin
          F_writedone_reg <= PWDATA[0];
        end
        else if (PADDR == 32'h0000000C) begin
          B_writedone_reg <= PWDATA[0];
        end
        else if (PADDR == 32'h0000000D) begin
          rdy_to_transmit_reg <= PWDATA[0];
        end
        else if (PADDR == 32'h0000000E) begin
          transmit_done_reg <= PWDATA[0];
        end
      end
    end
  end
  assign F_writedone_respond = F_writedone_reg;
  assign B_writedone_respond = B_writedone_reg;
  assign rdy_to_transmit_respond = rdy_to_transmit_reg;
  assign transmit_done_respond = transmit_done_reg;
endmodule

