module I_SQRT_2(
input wire [31:0] n,
input wire CLK,
input wire RST_n,
input wire EN,
input wire SEL,
output wire VAL,
output wire Z,
output wire [31:0] out_sqrt
); 

reg [31:0] x_0 = 1.0;
reg [31:0] x_i = 1.0;
reg [31:0] x_i_mux = 1.0;
reg [31:0] x_next = 1.0;
reg [31:0] sqrt = 1.0;
reg val_comb = 1'b0;
reg z_comb = 1'b0;
reg val_ff = 1'b0;
reg z_ff = 1'b0;
  always @(posedge CLK, posedge RST_n) begin
    if((RST_n == 1'b0)) begin
      x_0 <= 1.0;
      x_i <= 1.0;
      x_i_mux <= 1.0;
      x_next <= 1.0;
      sqrt <= 1.0;
      val_comb <= 1'b0;
      z_comb <= 1'b0;
      val_ff <= 1'b0;
      z_ff <= 1'b0;
    end else begin
      if((n == 32'b0)) begin
        sqrt <= 32'b0;
        val_comb <= 1'b0;
        z_comb <= 1'b1;
      end
      else begin
        if((x_next >= x_i)) begin
          sqrt <= x_i;
          val_comb <= 1'b1;
          z_comb <= 1'b0;
        end
        else begin
          val_comb <= 1'b0;
          z_comb <= 1'b0;
        end
      end
      x_i_mux <= x_next;
      x_i <= x_i_mux;
    end
  end
  assign out_sqrt = out_sqrt_reg;
  always @(posedge CLK, posedge RST_n) begin
    if((RST_n == 1'b0)) begin
      out_sqrt_reg <= 32'b0;
    end else begin
      if((EN == 1'b1)) begin
        out_sqrt_reg <= sqrt;
      end
    end
  end
  assign x_next = x_i + (n / x_i);
  assign x_i_mux = SEL == 1'b0 ? x_i : x_next;
  assign Z = n == 32'b0 ? 1'b1 : 1'b0;
  assign VAL = val_comb;
  assign Z = z_comb;
  assign val_ff = val_comb;
  assign z_ff = z_comb;
  always @(posedge CLK, posedge RST_n) begin
    if((RST_n == 1'b0)) begin
      val_ff <= 1'b0;
      z_ff <= 1'b0;
    end else begin
      if((EN == 1'b1)) begin
        val_ff <= val_comb;
        z_ff <= z_comb;
      end
    end
  end
  always @(posedge CLK, posedge RST_n) begin
    if((RST_n == 1'b0)) begin
      val_comb <= 1'b0;
      z_comb <= 1'b0;
    end else begin
      if((EN == 1'b1)) begin
        val_comb <= val_ff;
        z_comb <= z_ff;
      end
    end
  end
endmodule

module cycloneii_latch(D, ENA, PRE, CLR, Q);

   input D;
   input ENA, PRE, CLR;
   output Q;
reg q_out;

   buf (D_in, D);
   buf (ENA_in, ENA);
   buf (PRE_in, PRE);
   buf (CLR_in, CLR);

   initial
     begin
	q_out <= 1'b0;
     end

   specify
      $setuphold (posedge ENA, posedge D, 0, 0, "D_latch") ;
      $setuphold (posedge ENA, negedge D, 0, 0, "D_latch") ;
      $setuphold (posedge ENA, posedge PRE, 0, 0, "PRE_latch") ;
      $setuphold (posedge ENA, negedge PRE, 0, 0, "PRE_latch") ;
      $setuphold (posedge ENA, posedge CLR, 0, 0, "CLR_latch") ;
      $setuphold (posedge ENA, negedge CLR, 0, 0, "CLR_latch") ;
      (posedge ENA => (Q +: q_out)) = 0 ;
      (negedge ENA => (Q +: q_out)) = 0 ;
      (posedge PRE => (Q +: q_out)) = 0 ;
      (negedge PRE => (Q +: q_out)) = 0 ;
      (posedge CLR => (Q +: q_out)) = 0 ;
      (negedge CLR => (Q +: q_out)) = 0 ;
   endspecify

   always @ (D_in or ENA_in or PRE_in or CLR_in)
     begin
	if (PRE_in == 1'b1)
	  begin
	     q_out <= 1'b0;
	  end
	else if (CLR_in == 1'b1)
	  begin
	     q_out <= 1'b0;
	  end
	else if ((ENA_in == 1'b1) & (D_in == 1'b1))
	  begin
	     q_out <= 1'b1;
	  end
	else if ((ENA_in == 1'b1) & (D_in == 1'b0))
	  begin
	     q_out <= 1'b0;
	  end
     end

   buf (Q, q_out);

endmodule

