module UART_rx(
input wire clk,
input wire reset,
input wire rx_data_in,
output reg [7:0] rx_data_out
); 

parameter [31:0] BAUD_RATE=115200;
parameter [31:0] COUNTER_BIT=16;
parameter [1:0]
  IDLE = 0,
  START = 1,
  DATA = 2,
  STOP = 3;
reg [1:0] state = IDLE;
reg [31:0] counter = 0;
reg [31:0] counter_bit = 0;
reg [7:0] rx_data = 1'b0;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      state <= IDLE;
      counter <= 0;
      counter_bit <= 0;
      rx_data <= 8'b00000000;
    end else begin
      case(state)
      IDLE : begin
        if((counter == (COUNTER_BIT - 1))) begin
          counter <= 0;
          if((rx_data_in == 1'b0)) begin
            state <= START;
          end
        end
        else begin
          counter <= counter + 1;
        end
      end
      START : begin
        if((counter == (COUNTER_BIT - 1))) begin
          counter <= 0;
          state <= DATA;
        end
        else begin
          counter <= counter + 1;
        end
      end
      DATA : begin
        if((counter == (COUNTER_BIT - 1))) begin
          counter <= 0;
          if((rx_data_in == 1'b1)) begin
            state <= STOP;
          end
          else begin
            state <= DATA;
          end
        end
        else begin
          counter <= counter + 1;
        end
      end
      STOP : begin
        if((counter == (COUNTER_BIT - 1))) begin
          counter <= 0;
          rx_data_out <= rx_data;
          state <= IDLE;
        end
        else begin
          counter <= counter + 1;
        end
      end
      default : begin
        state <= IDLE;
        counter <= 0;
        counter_bit <= 0;
        rx_data <= 8'b00000000;
      end
      endcase
    end
  end
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      counter_bit <= 0;
      rx_data <= 8'b00000000;
    end else begin
      case(state)
      IDLE : begin
        if((counter_bit == (COUNTER_BIT - 1))) begin
          counter_bit <= 0;
        end
        else begin
          counter_bit <= counter_bit + 1;
        end
      end
      START : begin
        if((counter_bit == (COUNTER_BIT - 1))) begin
          counter_bit <= 0;
        end
        else begin
          counter_bit <= counter_bit + 1;
        end
      end
      DATA : begin
        if((counter_bit == (COUNTER_BIT - 1))) begin
          counter_bit <= 0;
        end
        else begin
          counter_bit <= counter_bit + 1;
        end
      end
      STOP : begin
        if((counter_bit == (COUNTER_BIT - 1))) begin
          counter_bit <= 0;
        end
        else begin
          counter_bit <= counter_bit + 1;
        end
      end
      default : begin
        counter_bit <= 0;
        rx_data <= 8'b00000000;
      end
      endcase
    end
  end
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      rx_data <= 8'b00000000;
    end else begin
      case(state)
      IDLE : begin
        rx_data <= 8'b00000000;
      end
      START : begin
        rx_data <= {rx_data[6:0],rx_data_in};
      end
      DATA : begin
        rx_data <= {rx_data[6:0],rx_data_in};
      end
      STOP : begin
        rx_data <= {rx_data[6:0],rx_data_in};
      end
      default : begin
        rx_data <= 8'b00000000;
      end
      endcase
    end
  end
endmodule

module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n = 30; 
parameter count = 4; 
reg [n-1:0]s_in; 
reg [1:0]delay; 
top t1(clk, reset, rxD, s_in, signal, counter); 
always @(posedge clk or posedge reset) 
begin 
if (reset) 
begin 
counter <= 0; 
delay <= 0; 
sout <= 0; 
end 
else 
begin 
if (counter == count) 
begin 
delay <= delay + 1; 
if (delay == 0) 
begin 
signal <= 1; 
counter <= 0; 
end 
end 
else 
begin 
sout <= {s_in, sout[n-1:1]}; 
counter <= counter + 1; 
end 
end 
end 
endmodule

