module twocmp(input [31:0]A,output [31:0]B);
genvar i;
    generate
        for(i=0;i<32;i=i+1)
        begin:twocmp_loop
            if(i==0)
            begin
                assign B[0] = A[0];
            end
            else
            begin
                assign B[i] = (A[0] | A[1] | A[2] | A[3] | A[4] | A[5] | A[6] | A[7] | A[8] | A[9] | A[10] | A[11] | A[12] | A[13] | A[14] | A[15] | A[16] | A[17] | A[18] | A[19] | A[20] | A[21] | A[22] | A[23] | A[24] | A[25] | A[26] | A[27] | A[28] | A[29] | A[30] | A[31]) ? ~A[i] : A[i];
            end
        end
    endgenerate
endmodule

module arbiter (
clock, 
reset, 
req_0,
req_1, 
gnt_0,
gnt_1
);

input clock, reset, req_0, req_1;
output gnt_0, gnt_1;
reg gnt_0, gnt_1;

always @(posedge clock or posedge reset) begin
	if (reset) begin
		gnt_0 <= 0;
		gnt_1 <= 0;
	end
	else begin
		if (req_0) begin
			gnt_0 <= 1;
			gnt_1 <= 0;
		end
		else if (req_1) begin
			gnt_0 <= 0;
			gnt_1 <= 1;
		end
		else begin
			gnt_0 <= 0;
			gnt_1 <= 0;
		end
	end
end

endmodule

module NAND3C(Y,A,B,C);
 input A,B,C;
 output Y;
wire NET_0_0;

 not	INV_115(A_, A);
 not	INV_116(B_, B);
 and      U707(NET_0_0, A_, B_);
 nand     U708(Y, NET_0_0, C);

       specify

		specparam tpdLH_A_to_Y = (0.1:0.1:0.1);
		specparam tpdHL_A_to_Y = (0.1:0.1:0.1);
		specparam tpdLH_B_to_Y = (0.1:0.1:0.1);
		specparam tpdHL_B_to_Y = (0.1:0.1:0.1);
		specparam tpdLH_C_to_Y = (0.1:0.1:0.1);
		specparam tpdHL_C_to_Y = (0.1:0.1:0.1);
		specparam MacroType = "comb";



		(A => Y ) = ( tpdLH_A_to_Y, tpdHL_A_to_Y );
		(B => Y ) = ( tpdLH_B_to_Y, tpdHL_B_to_Y );
		(C => Y ) = ( tpdLH_C_to_Y, tpdHL_C_to_Y );
   endspecify

endmodule

module th22i
    #(parameter INITIAL = 0) (
      input	 init,
      input	 A, 
      input	 B, 
      output reg Q);
initial Q = INITIAL;
   always @(A or B) begin
      if (init)
	Q <= #1 INITIAL;
      else if (A & B)
	Q <= #INITIAL 1;
      else if (!A & !B)
	Q <= #3 0;
   end
endmodule

