            if (Digit3 >= 10) begin
                Digit3 = Digit3 + 3;
            end
            if (Digit2 >= 10) begin
                Digit2 = Digit2 + 3;
            end
            if (Digit1 >= 10) begin
                Digit1 = Digit1 + 3;
            end
            if (Digit0 >= 10) begin
                Digit0 = Digit0 + 3;
            end
            Digit3 = Digit3 << 1;
            Digit3[0] = Digit2[3];
            Digit2 = Digit2 << 1;
            Digit2[0] = Digit1[3];
            Digit1 = Digit1 << 1;
            Digit1[0] = Digit0[3];
            Digit0 = Digit0 << 1;
            Digit0[0] = Input[i];
        end
    end
endmodule

