module bus_mux (din,sel,dout);

input [TOTAL_DAT-1 : 0] din;
input [SEL_WIDTH-1:0] sel;
output [DAT_WIDTH-1:0] dout;
parameter DAT_WIDTH = 32;
parameter TOTAL_DAT = 10;
parameter SEL_WIDTH = 2;

wire [DAT_WIDTH-1:0] dout;
wire [TOTAL_DAT-1:0] din_tmp;
wire [SEL_WIDTH-1:0] sel_tmp;

genvar i;
generate
	for (i=0;i<SEL_WIDTH;i=i+1) begin: sel_loop
		for (i=0;i<TOTAL_DAT;i=i+1) begin: dat_loop
			assign din_tmp[i*DAT_WIDTH + DAT_WIDTH-1 : i*DAT_WIDTH] = din[(i+1)*DAT_WIDTH - 1 : i*DAT_WIDTH];
		end
	end
endgenerate

genvar j;
generate
	for (j=0;j<SEL_WIDTH;j=j+1) begin: sel_loop
		assign sel_tmp[j] = sel[j];
	end
endgenerate

assign dout = din_tmp[sel_tmp*DAT_WIDTH + DAT_WIDTH-1 : sel_tmp*DAT_WIDTH];

endmodule

