module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] h_disp=640;
parameter [31:0] h_front=16;
parameter [31:0] h_back=48;
parameter [31:0] h_retrace=96;
parameter [31:0] v_disp=480;
parameter [31:0] v_front=10;
parameter [31:0] v_back=33;
parameter [31:0] v_retrace=2;
reg [9:0] h_count_reg; reg [9:0] v_count_reg;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      h_count_reg <= {10{1'b0}};
      v_count_reg <= {10{1'b0}};
    end else begin
      h_count_reg <= h_count_reg + 1;
      v_count_reg <= v_count_reg + 1;
    end
  end
  always @(h_count_reg, v_count_reg) begin
    if((h_count_reg < h_disp) && (v_count_reg < v_disp)) begin
      active <= 1'b1;
    end
    else begin
      active <= 1'b0;
    end
    if((h_count_reg < h_front)) begin
      hsync <= 1'b1;
    end
    else if((h_count_reg < h_front + h_back)) begin
      hsync <= 1'b0;
    end
    else if((h_count_reg < h_front + h_back + h_retrace)) begin
      hsync <= 1'b1;
    end
    else begin
      hsync <= 1'b0;
    end
    if((v_count_reg < v_front)) begin
      vsync <= 1'b1;
    end
    else if((v_count_reg < v_front + v_back)) begin
      vsync <= 1'b0;
    end
    else if((v_count_reg < v_front + v_back + v_retrace)) begin
      vsync <= 1'b1;
    end
    else begin
      vsync <= 1'b0;
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
endmodule

