module TopModule(
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    output reg walk_left
);
localparam [1:0] STATE_WALK_LEFT = 2'b00;
    localparam [1:0] STATE_WALK_RIGHT = 2'b01;
    localparam [1:0] STATE_WALK_BOTH = 2'b10;
    localparam [1:0] STATE_WALK_NONE = 2'b11;
    reg [1:0] state;
    always @(posedge clk) begin
        if (areset) begin
            state <= STATE_WALK_LEFT;
            walk_left <= 1'b1;
