            case (state)
                STATE_WALK_LEFT: begin
                    if (bump_left) begin
                        state <= STATE_WALK_RIGHT;
                        walk_left <= 1'b0;
                    end
                    else if (bump_right) begin
                        state <= STATE_WALK_LEFT;
                        walk_left <= 1'b1;
                    end
                    else begin
                        state <= STATE_WALK_NONE;
                        walk_left <= 1'b1;
                    end
                end
                STATE_WALK_RIGHT: begin
                    if (bump_right) begin
                        state <= STATE_WALK_LEFT;
                        walk_left <= 1'b0;
                    end
                    else if (bump_left) begin
                        state <= STATE_WALK_RIGHT;
                        walk_left <= 1'b1;
                    end
                    else begin
                        state <= STATE_WALK_NONE;
                        walk_left <= 1'b1;
                    end
                end
                STATE_WALK_BOTH: begin
                    if (bump_left) begin
                        state <= STATE_WALK_RIGHT;
                        walk_left <= 1'b0;
                    end
                    else if (bump_right) begin
                        state <= STATE_WALK_LEFT;
                        walk_left <= 1'b1;
                    end
                    else begin
                        state <= STATE_WALK_NONE;
                        walk_left <= 1'b1;
                    end
                end
                default: begin
                    state <= STATE_WALK_LEFT;
                    walk_left <= 1'b1;
                end
            endcase
        end
    end
endmodule

