module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);
reg [1:0] state;
  reg [1:0] next_state;
  reg falling;
  reg digging;
  reg aaah;
  assign walk_left = state[0];
  assign walk_right = state[1];
  assign aaah = aaah;
  assign digging = digging;
  always @(posedge clk) begin
    if (areset) begin
      state <= 2'b00;
    end else begin
      state <= next_state;
    end
  end
  always @(state, ground, falling, dig) begin
    next_state = state;
    case (state)
      2'b00: begin
        if (ground == 1'b0) begin
          next_state = 2'b01;
        end
        if (dig == 1'b1) begin
          next_state = 2'b10;
        end
      end
      2'b01: begin
        if (bump_left == 1'b1) begin
          next_state = 2'b10;
        end
        if (bump_right == 1'b1) begin
          next_state = 2'b00;
        end
      end
      2'b10: begin
        if (bump_right == 1'b1) begin
          next_state = 2'b11;
        end
        if (bump_left == 1'b1) begin
          next_state = 2'b00;
        end
      end
      2'b11: begin
        if (bump_left == 1'b1) begin
          next_state = 2'b00;
        end
        if (bump_right == 1'b1) begin
          next_state = 2'b10;
        end
      end
      default: next_state = 2'b00;
    endcase
  end
  always @(posedge clk) begin
    if (areset) begin
      falling <= 1'b0;
    end else begin
      if (state == 2'b00) begin
        falling <= 1'b0;
      end else begin
        falling <= 1'b1;
      end
    end
  end
  always @(posedge clk) begin
    if (areset) begin
      digging <= 1'b0;
    end else begin
      if (state == 2'b00) begin
        digging <= 1'b0;
      end else begin
        if (dig == 1'b1) begin
          digging <= 1'b1;
        end
      end
    end
  end
  always @(posedge clk) begin
    if (areset) begin
      aaah <= 1'b0;
    end else begin
      if (state == 2'b00) begin
        aaah <= 1'b0;
      end else begin
        if (ground == 1'b0) begin
          aaah <= 1'b1;
        end
      end
    end
  end
endmodule

